    @keyframes robeWave {
      0%, 100% { d: path('M 560 280 Q 555 320 550 360 L 570 360 Q 565 320 560 280 Z'); }
      50% { d: path('M 560 280 Q 550 320 545 360 L 565 360 Q 560 320 560 280 Z'); }
    }

    .cloud {
      animation: floatCloud 8s ease-in-out infinite;
    }

    @keyframes floatCloud {
      0%, 100% { transform: translate(0, 0); }
      50% { transform: translate(200px, -20px); }
    }

