        <circle cx="540" cy="320" r="6" fill="#E9A568"/>

        <!-- 排气管 -->
        <path d="M 430 375 L 380 385 Q 375 385 375 380 Q 375 375 380 375 L 430 370" 
              fill="#1E2636" stroke="#6B8CAE" stroke-width="2"/>

