        <path d="M 560 290 Q 520 320 518 330" stroke="#E9A568" stroke-width="4" fill="none" stroke-linecap="round"/>

        <!-- 头部 -->
        <circle cx="580" cy="250" r="22" fill="#E9A568"/>

        <!-- 道冠 -->
        <path d="M 560 235 Q 580 220 600 235 L 595 245 L 565 245 Z" 
              fill="url(#goldGrad)" stroke="#FFC870" stroke-width="1"/>
        <circle cx="580" cy="228" r="5" fill="#FFC870"/>

