          <path d="M 580 268 Q 580 285 580 295" stroke="#f0f0f0" stroke-width="3" fill="none" stroke-linecap="round"/>
          <path d="M 590 265 Q 595 280 600 290" stroke="#f0f0f0" stroke-width="3" fill="none" stroke-linecap="round"/>
