        <g opacity="0.6">
          <line x1="480" y1="300" x2="470" y2="285" stroke="#f0f0f0" stroke-width="1"/>
          <line x1="480" y1="300" x2="468" y2="290" stroke="#f0f0f0" stroke-width="1"/>
          <line x1="480" y1="300" x2="466" y2="295" stroke="#f0f0f0" stroke-width="1"/>
          <line x1="480" y1="300" x2="465" y2="300" stroke="#f0f0f0" stroke-width="1"/>
          <line x1="480" y1="300" x2="466" y2="305" stroke="#f0f0f0" stroke-width="1"/>
          <line x1="480" y1="300" x2="468" y2="310" stroke="#f0f0f0" stroke-width="1"/>
          <line x1="480" y1="300" x2="470" y2="315" stroke="#f0f0f0" stroke-width="1"/>
        </g>
      </g>

