        <animate attributeName="cy" values="200;150;200" dur="3s" repeatCount="indefinite"/>
        <animate attributeName="opacity" values="0.6;0.2;0.6" dur="3s" repeatCount="indefinite"/>
      </circle>
      <circle cx="750" cy="180" r="2" fill="#FFC870" opacity="0.5">
